// Checks the committed language catalog (src/domains/locale/domain/language-data.json and the
// names files in language-names/), generated by `pnpm update:language-data`, so a bad update or a
// hand edit can't slip in. Decisions: docs/plan/M1-languages.md.
import { readdirSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  EXCLUDED_CODES,
  serializeLanguageData,
  serializeLanguageNames,
  type LanguageDataFile,
  type LanguageNamesFile,
} from './language-data.ts';

const text = readFileSync(
  new URL('../src/domains/locale/domain/language-data.json', import.meta.url),
  'utf8',
);
const data = JSON.parse(text) as LanguageDataFile;
const tags = new Set(data.languages.map((language) => language.tag));
const find = (tag: string) => data.languages.find((language) => language.tag === tag);

describe('the language catalog', () => {
  it('is exactly what the generator writes (no hand edits, stable formatting)', () => {
    expect(serializeLanguageData(data)).toBe(text);
  });

  it('records when it was generated, and from what', () => {
    expect(data.generated).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(data.sources.map((source) => source.license)).toEqual([
      expect.stringContaining('GPL-2.0-or-later'),
      'GPL-2.0-or-later',
    ]);
  });

  it('has over 1,400 languages, sorted, with unique tags and MediaWiki codes', () => {
    expect(data.languages.length).toBeGreaterThan(1400);
    const lower = data.languages.map((language) => language.tag.toLowerCase());
    expect(new Set(lower).size).toBe(lower.length);
    expect(new Set(data.languages.map((language) => language.mw)).size).toBe(lower.length);
    const sorted = [...data.languages].sort((a, b) => (a.tag < b.tag ? -1 : 1));
    expect(data.languages).toEqual(sorted);
  });

  it('gives every language a well-formed tag, a direction, and an English name', () => {
    const problems = data.languages.flatMap((language) => {
      const found: string[] = [];
      try {
        Intl.getCanonicalLocales(language.tag);
      } catch {
        found.push(`${language.tag}: malformed tag`);
      }
      // The file is data from outside: check the value, not just its declared type.
      const dir: string = language.dir;
      if (dir !== 'ltr' && dir !== 'rtl') found.push(`${language.tag}: direction`);
      if (!language.name.trim()) found.push(`${language.tag}: no English name`);
      if (language.autonym !== null && language.autonym.trim() === '')
        found.push(`${language.tag}: empty autonym`);
      return found;
    });
    expect(problems).toEqual([]);
  });

  it('is right to left for every language written in a right-to-left script', () => {
    const rtlScripts = new Set(data.rtlScripts);
    const wrong = data.languages.filter(
      (language) =>
        language.script !== undefined && rtlScripts.has(language.script) && language.dir !== 'rtl',
    );
    expect(wrong.map((language) => language.tag)).toEqual([]);
  });

  it('only refers to languages it has (aliases, fallbacks, territories)', () => {
    expect(Object.values(data.aliases).filter((tag) => !tags.has(tag))).toEqual([]);
    expect(
      data.languages.flatMap((l) => (l.fallbacks ?? []).filter((tag) => !tags.has(tag))),
    ).toEqual([]);
    expect(
      Object.values(data.territories)
        .flat()
        .filter((tag) => !tags.has(tag)),
    ).toEqual([]);
  });

  it('has lowercase aliases that never shadow a real tag', () => {
    const lowerTags = new Set([...tags].map((tag) => tag.toLowerCase()));
    for (const alias of Object.keys(data.aliases)) {
      expect(alias).toBe(alias.toLowerCase());
      expect(lowerTags.has(alias), alias).toBe(false);
    }
  });

  it('leaves out MediaWiki special codes', () => {
    for (const code of EXCLUDED_CODES)
      expect(data.languages.some((l) => l.mw === code)).toBe(false);
  });

  it.each<[string, Partial<{ dir: string; autonym: string; mw: string }>]>([
    ['en', { dir: 'ltr', autonym: 'English' }],
    ['he', { dir: 'rtl', autonym: 'עברית' }],
    ['ar', { dir: 'rtl', autonym: 'العربية' }],
    ['fa', { dir: 'rtl' }],
    ['ur', { dir: 'rtl' }],
    ['yi', { dir: 'rtl' }],
    ['ydd', { dir: 'rtl' }],
    ['pt-BR', { dir: 'ltr', mw: 'pt-br' }],
    ['sr-Latn', { dir: 'ltr' }],
    ['tl', {}],
    ['fil', {}],
    ['sh', {}],
    ['de-x-formal', { mw: 'de-formal' }],
  ])('knows %s', (tag, expected) => {
    expect(find(tag)).toMatchObject(expected);
  });

  it('maps old and MediaWiki codes to tags (codes that differ only in case need no alias)', () => {
    expect(data.aliases).toMatchObject({
      'sr-el': 'sr-Latn',
      'be-x-old': 'be-tarask',
      'zh-min-nan': 'nan',
    });
    expect(data.aliases['pt-br']).toBeUndefined();
  });

  it('knows which languages are spoken in a region, most spoken first', () => {
    expect(data.territories.IL?.slice(0, 3)).toEqual(['he', 'en', 'ar']);
  });
});

const namesFolder = new URL('../src/domains/locale/domain/language-names/', import.meta.url);
const namesFiles = readdirSync(namesFolder)
  .filter((file) => file.endsWith('.json'))
  .sort();
const uiLanguages = readdirSync(new URL('../src/ui/i18n/messages/', import.meta.url))
  .filter((file) => file.endsWith('.json'))
  .map((file) => file.slice(0, -'.json'.length))
  .filter((language) => language !== 'en' && language !== 'qqq')
  .sort();

describe('the language names files', () => {
  it('has one file for each interface language besides English, and no others', () => {
    expect(namesFiles.map((file) => file.slice(0, -'.json'.length))).toEqual(uiLanguages);
  });

  describe.each(namesFiles)('%s', (file) => {
    const fileText = readFileSync(new URL(file, namesFolder), 'utf8');
    const names = JSON.parse(fileText) as LanguageNamesFile;

    it('is exactly what the generator writes', () => {
      expect(serializeLanguageNames(names)).toBe(fileText);
    });

    it('names only languages the catalog has, sorted, never empty', () => {
      expect(Object.keys(names).filter((tag) => !tags.has(tag))).toEqual([]);
      expect(Object.keys(names)).toEqual([...Object.keys(names)].sort((a, b) => (a < b ? -1 : 1)));
      expect(Object.values(names).filter((name) => name.trim() === '')).toEqual([]);
    });

    it('names most languages', () => {
      expect(Object.keys(names).length).toBeGreaterThan(data.languages.length / 2);
    });
  });

  it('names Brazilian Portuguese in Hebrew', () => {
    const he = JSON.parse(
      readFileSync(new URL('he.json', namesFolder), 'utf8'),
    ) as LanguageNamesFile;
    expect(he['pt-BR']).toBeDefined();
    expect(find('pt-BR')?.name).toBe('Brazilian Portuguese');
  });
});
